using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program {
    static void Main() {
        var build = BinaryLog.ReadBuild("/tmp/sv-a7bec1e0a1ed4a85bc47c476ddd2fa71/build.binlog");

        // Get CscCommandLineArgs to find actual compiler invocations
        Console.WriteLine("=== CSC COMMAND LINE (Core) ===");
        build.VisitAllChildren<Task>(task => {
            if (task.Name == "Csc") {
                var proj = task.GetNearestParent<Project>();
                if (proj != null && proj.ProjectFile != null && proj.ProjectFile.Contains("Core")) {
                    Console.WriteLine($"Project: {proj.ProjectFile}");
                    foreach (var child in task.Children) {
                        if (child is Message msg && msg.Text != null && msg.Text.Contains("error"))
                            Console.WriteLine($"  MSG: {msg.Text}");
                    }
                }
            }
        });

        // Look for diagnostic messages in Core build
        Console.WriteLine("\n=== Messages containing 'Models.cs' ===");
        build.VisitAllChildren<Message>(msg => {
            if (msg.Text != null && msg.Text.Contains("Models.cs"))
                Console.WriteLine($"  {msg.Text.Substring(0, Math.Min(200, msg.Text.Length))}");
        });

        // Check if Core had compiler errors too
        Console.WriteLine("\n=== Compiler output for Core ===");
        build.VisitAllChildren<CscTask>(csc => {
            var proj = csc.GetNearestParent<Project>();
            Console.WriteLine($"CSC in: {proj?.ProjectFile}");
            Console.WriteLine($"  CommandLine: {csc.CommandLineArguments?.Substring(0, Math.Min(300, csc.CommandLineArguments?.Length ?? 0))}");
        });
    }
}
EOF
